import json
from pathlib import Path
root = Path(__file__).parent
r = json.loads((root/'results.json').read_text())
a, b = r['results']
rows = ''.join(f'<tr><th>{x["label"]}</th><td>{x["requests"]}</td><td>{x["delaysOver500ms"]}</td><td>{x["worstMs"]:,} ms</td></tr>' for x in [a,b])
charts = ''.join(f'<div class="chart"><strong>{x["label"]}</strong><div class="bars">' + ''.join(f'<i title="{ms} ms" style="height:{max(2,min(100,ms/15))}%"></i>' for ms in x['latenciesMs']) + '</div></div>' for x in [a,b])
html = '''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Process tracking: fix verified</title><style>
*{box-sizing:border-box}body{margin:0;background:#f4f2eb;color:#233b39;font:16px/1.6 system-ui,sans-serif}main{max-width:800px;margin:auto;padding:42px 28px}.eyebrow{font-size:12px;letter-spacing:.12em;text-transform:uppercase;font-weight:700;color:#576e65}h1{font:600 35px/1.15 Georgia,serif;margin:14px 0 20px}p{margin:12px 0}.lead{font-size:19px}.panel{margin:26px 0;padding:24px;background:white;border-radius:12px;box-shadow:0 3px 15px #163e3010}h2{font-size:18px;margin:0 0 12px}.pill{display:inline-block;background:#d9ebdc;padding:5px 12px;border-radius:20px;font-size:13px;font-weight:650}table{width:100%;border-collapse:collapse;font-size:14px}th,td{text-align:left;padding:12px 6px;border-bottom:1px solid #e1e6e2}thead{color:#65776e;font-size:12px}tr:last-child th,tr:last-child td{border:0}.small{font-size:13px;color:#5a6d65}.chart{margin:16px 0}.chart strong{font-size:13px}.bars{height:90px;display:flex;align-items:end;gap:3px;border-bottom:1px solid #ddd}.bars i{display:block;flex:1;min-width:2px;background:#bc6558}.chart+.chart i{background:#57977e}code{font-size:14px}footer{border-top:1px solid #cdd6cb;padding-top:16px;font-size:13px;color:#586c61}
</style><main><div class="eyebrow">Obeya · Process tracking</div><h1>The logs identify a blocking call.<br>The fix is already on main.</h1><span class="pill">Verified · no additional code change needed</span><p class="lead">The reported freezes come from waiting synchronously for the process list. Main already reads that list in the background, so a slow inspection can finish while pages and agent messages keep flowing.</p><section class="panel"><h2>A deliberately slow process list</h2><p>Both versions used the actual process tracker with a process-list command delayed by 1.2 seconds. An independent client requested a page from a small HTTP server running alongside each tracker for roughly 6.5 seconds.</p><table><thead><tr><th>Version</th><th>Responses</th><th>Waits ≥ 500 ms</th><th>Longest wait</th></tr></thead><tbody>ROWS</tbody></table>CHARTS<p class="small">Each bar is one measured HTTP response; the vertical scale is the same in both rows. Requests are made sequentially, with 100 ms between responses.</p></section><section class="panel"><h2>What is already fixed</h2><p>Commit <code>6971a5a8</code>, landed November 4, switches active tracking to asynchronous process snapshots on macOS, Linux and Windows. Tracking and cleanup stay ordered, and cleanup still verifies process creation identities before signalling anything.</p><p>The blocking process-table reader is now used only for crash recovery at startup, before the server begins serving pages.</p></section><section class="panel"><h2>Verification scope</h2><p>This is a controlled reproduction on macOS with a minimal HTTP harness. It confirms the reported blocking mechanism and its fix; it is not a production latency benchmark or a claim that every possible server stall is resolved.</p><p id="checks">CHECKS</p></section><footer>Measured DATE. Compared the parent of fix 6971a5a8 with current checkout ad926d62. Repository files were left unchanged.</footer></main></html>'''
html=html.replace('ROWS',rows).replace('CHARTS',charts).replace('DATE',r['measuredAt']).replace('CHECKS','Type checking passed. All 28 process-tracking and crash-recovery checks passed; the native Windows check was skipped on macOS. The full suite had 2,108 passes, 24 skips and one unrelated registered-extension failure, reproduced in isolation and proposed as a separate task.')
(root/'index.html').write_text(html)
